test('예산 예약 경합 — 예약 중 금액까지 넣어 한도를 넘는 두 번째 예약은 되돌린다(45)', async () => {
  const { db, env, done } = await freshDb();
  try {
    const { Tx } = await import('../src/worker/db/client');
