test('운영자 제공 모델(Workers AI 바인딩) — 형식 변환·인자 없는 도구·깨진 인자·옛 형식·한도', async () => {
  const { workersAiAdapter } = await import('../src/worker/adapters/llm/workers-ai');
  const { platformAvailable, platformInfo } = await import('../src/worker/domain/runs');
  const seen: { model: string; inputs: { messages: { role: string; content: string | null; tool_calls?: { function: { arguments: string } }[] }[]; tools?: unknown[] } }[] = [];
  let reply: unknown = {
    model: '@cf/zai-org/glm-4.7-flash',
    choices: [{ finish_reason: 'tool_calls', message: { role: 'assistant', content: null, tool_calls: [{ id: 'c1', type: 'function', function: { name: 'list_projects', arguments: '' } }, { id: 'c2', type: 'function', function: { name: 'get', arguments: '{"a":1}{"a":2}' } }] } }],
    usage: { prompt_tokens: 120, completion_tokens: 30 },
  };
  const env = { PLATFORM_MODEL: 'on', AI: { run: async (model: string, inputs: never) => (seen.push({ model, inputs }), reply) } } as unknown as Env;
  const t = { provider: 'workers_ai' as const, baseUrl: '', model: '@cf/zai-org/glm-4.7-flash', apiKey: '', allowProviderFallback: false };
  const req = { system: '시스템', messages: [{ role: 'user' as const, content: '현황' }], tools: [{ name: 'list_projects', description: '목록', inputSchema: { type: 'object', properties: {} } }], maxOutputTokens: 512, effort: 'medium' as const, timeoutMs: 5000 };
  const r1 = await workersAiAdapter.generate(env, t, req);
  expect(seen[0]!.model).toBe('@cf/zai-org/glm-4.7-flash');
  expect(seen[0]!.inputs.tools).toHaveLength(1);
  // 인자 없는 도구는 {}, 두 객체를 붙인 깨진 인자는 오류 표시(엔진이 '인자 오류'로 돌려준다)
  expect(r1.toolCalls[0]).toEqual({ id: 'c1', name: 'list_projects', args: {} });
  expect(r1.toolCalls[1]!.args).toHaveProperty('__invalid_json');
  expect(r1.usage).toMatchObject({ inputTokens: 120, outputTokens: 30 });
  // 다음 호출에 되돌려 보낼 때 깨진 인자는 {} 로(Workers AI 는 객체가 아닌 인자를 거절한다), content null 은 ''
  reply = { response: '완료했습니다.', usage: { prompt_tokens: 200, completion_tokens: 10 } }; // 옛 형식
  const r2 = await workersAiAdapter.generate(env, t, {
    ...req,
    messages: [...req.messages, { role: 'assistant', provider: 'workers_ai', raw: r1.raw, text: '' }, { role: 'tool_results', results: [{ callId: 'c1', name: 'list_projects', content: '[]', isError: false }, { callId: 'c2', name: 'get', content: '인자 오류', isError: true }] }],
  });
  const replay = seen[1]!.inputs.messages.find((m) => m.role === 'assistant')!;
  expect(replay.content).toBe('');
  expect(replay.tool_calls!.map((x) => x.function.arguments)).toEqual(['', '{}']);
  expect(r2.text).toBe('완료했습니다.');
  expect(r2.toolCalls).toEqual([]);
  // 바인딩 오류는 분류해서 돌려준다(키 문자열 없음)
  (env as unknown as { AI: { run: () => Promise<never> } }).AI.run = async () => {
    throw new Error('3040: Capacity temporarily exceeded, please try again.');
  };
  await expect(workersAiAdapter.generate(env, t, req)).rejects.toMatchObject({ code: 'model_rate_limited' });
  // 운영자 월 한도 — 이번 달 운영자 부담 사용액이 한도에 닿으면 새 실행에 내주지 않는다
  const db = (n: number) => ({ prepare: () => ({ bind: () => ({ first: async () => ({ n }) }) }) });
  expect(await platformAvailable({ ...env, DB: db(9_999_999) } as unknown as Env)).toBe(true);
  expect(await platformAvailable({ ...env, DB: db(10_000_000) } as unknown as Env)).toBe(false);
  expect(await platformAvailable({ ...env, PLATFORM_MONTHLY_CAP_MICROS: '50000000', DB: db(10_000_000) } as unknown as Env)).toBe(true);
  expect(await platformAvailable({ PLATFORM_MODEL: 'on', DB: db(0) } as unknown as Env)).toBe(false); // 바인딩 없음
  const info = await platformInfo({ ...env, DB: db(0) } as unknown as Env);
  expect(info).toMatchObject({ available: true, model: '@cf/zai-org/glm-4.7-flash', label: 'GLM-4.7 Flash (Workers AI)', pricing: { input: 60_500, output: 400_000 } });
});

