test('문서 변환 — 서명 확인·PDF 속성 표 제거·글자 없는 결과 거절', async () => {
  const { signatureOk, tidyMarkdown, convertDocument } = await import('../src/worker/adapters/documents');
  const b = (s: string | number[]) => (typeof s === 'string' ? new TextEncoder().encode(s) : new Uint8Array(s));
  expect(signatureOk('pdf', b('%PDF-1.7 ...'))).toBe(true);
  expect(signatureOk('pdf', b('MZ\x90'))).toBe(false);
  expect(signatureOk('docx', b([0x50, 0x4b, 0x03, 0x04, 1]))).toBe(true);
  expect(signatureOk('xlsx', b('%PDF-'))).toBe(false);
  expect(signatureOk('xls', b([0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1]))).toBe(true);
  expect(signatureOk('html', b('<!doctype html><p>안녕'))).toBe(true);
  expect(signatureOk('html', b([0x3c, 0x00, 0x01]))).toBe(false);
  expect(tidyMarkdown('# a.pdf\n## Metadata\n- PDFFormatVersion=1.7\n- Creator=Chrome\n\n## Contents\n본문')).toBe('# a.pdf\n\n## Contents\n본문');
  // 실제 AI 바인딩 모양(배열 결과)·오류·빈 결과
  const seenTypes: string[] = [];
  const env = (r: unknown) => ({ FILE_UPLOADS: 'documents', AI: { toMarkdown: async (d: { blob: Blob }) => (seenTypes.push(d.blob.type), r) } }) as unknown as Env;
  const pdf = b('%PDF-1.7 body');
  expect(await convertDocument(env([{ name: 'a.pdf', format: 'markdown', data: '# a.pdf\n## Metadata\n- X=1\n\n견적 금액은 1,500,000원입니다' }]), 'a.pdf', 'pdf', pdf)).toEqual({ ok: true, text: '# a.pdf\n\n견적 금액은 1,500,000원입니다', via: 'workers_ai' });
  expect(seenTypes[0]).toBe('application/pdf'); // 형식이 비면 변환 서비스가 거절한다
  expect(await convertDocument(env({ format: 'error', error: 'encrypted' }), 'a.pdf', 'pdf', pdf)).toMatchObject({ ok: false, reason: expect.stringContaining('암호') });
  expect(await convertDocument(env({ format: 'markdown', data: '# scan.pdf\n\n' }), 'scan.pdf', 'pdf', pdf)).toMatchObject({ ok: false, reason: expect.stringContaining('글자를 찾지 못했습니다') });
  expect(await convertDocument(env({ format: 'markdown', data: 'x' }), 'a.docx', 'docx', pdf)).toMatchObject({ ok: false, reason: expect.stringContaining('형식이 아닙니다') });
  const slow = { FILE_UPLOADS: 'documents', AI: { toMarkdown: () => new Promise(() => {}) } } as unknown as Env;
  expect(await convertDocument(slow, 'a.pdf', 'pdf', pdf, 50)).toMatchObject({ ok: false, reason: expect.stringContaining('시간이 초과') });
});

test('자료 구절 — 문단을 묶어 자르고 위치를 기억, 낱말이 많이 맞는 구절이 앞', async () => {
  const { passages, passageScore } = await import('../src/worker/domain/knowledge');
  const text = `# 계약서\n\n제1조 목적\n\n${'일반 조항 내용입니다. '.repeat(80)}\n\n제5조 대금: 계약 금액은 1,800,000원이며 납기는 11월 14일이다.\n\n${'부칙 내용. '.repeat(60)}`;
  const ps = passages(text);
  expect(ps.length).toBeGreaterThanOrEqual(2);
  for (const p of ps) expect(text.slice(p.from, p.from + 20).trim().slice(0, 5)).toBe(p.text.slice(0, 5)); // 위치가 실제 본문과 맞다
  const best = ps.map((p) => ({ p, s: passageScore(p.text, ['금액', '납기']) })).sort((a, b) => b.s - a.s)[0]!;
  expect(best.p.text).toContain('1,800,000원');
  expect(passageScore('금액 금액 금액 금액 금액', ['금액'])).toBeLessThan(passageScore('금액 납기', ['금액', '납기']) + 5); // 같은 낱말 반복보다 다른 낱말이 맞는 쪽을 크게
  // 줄바꿈 없는 아주 긴 문단도 잘라서
  const flat = passages('가'.repeat(5000));
  expect(flat.length).toBeGreaterThan(3);
  expect(Math.max(...flat.map((p) => p.text.length))).toBeLessThanOrEqual(1120);
});

test('OAuth 발견 — 자원 표기 차이(끝의 /)는 같은 자원, 보호 자원 메타데이터가 없으면 옛 규격(출처 = 인증 서버)', async () => {
  const { discoverResource } = await import('../src/worker/adapters/mcp/oauth');
  const env = { EGRESS_MODE: 'public', APP_ORIGIN: 'https://agent.irumx.app' } as unknown as Env;
  const real = globalThis.fetch;
  const serve = (routes: Record<string, unknown>) => {
    globalThis.fetch = (async (input: RequestInfo | URL) => {
      const u = String(input instanceof Request ? input.url : input);
      const body = routes[u];
      return body === undefined ? new Response('not found', { status: 404 }) : new Response(JSON.stringify(body), { status: 200, headers: { 'Content-Type': 'application/json' } });
    }) as typeof fetch;
  };
  try {
    // Vercel 형: 서버가 끝에 / 를 붙여 밝힌다 → 같은 자원, 그 표기를 그대로 보낸다
    serve({ 'https://mcp.vendor-a.com/.well-known/oauth-protected-resource': { resource: 'https://mcp.vendor-a.com/', authorization_servers: ['https://vendor-a.com'] } });
    const a = await discoverResource(env, 'https://mcp.vendor-a.com', 'Bearer resource_metadata="https://mcp.vendor-a.com/.well-known/oauth-protected-resource"');
    expect(a.resource).toBe('https://mcp.vendor-a.com/');
    // 다른 자원은 여전히 거절
    serve({ 'https://mcp.vendor-a.com/.well-known/oauth-protected-resource': { resource: 'https://evil.example/', authorization_servers: ['https://vendor-a.com'] } });
    await expect(discoverResource(env, 'https://mcp.vendor-a.com', 'Bearer resource_metadata="https://mcp.vendor-a.com/.well-known/oauth-protected-resource"')).rejects.toMatchObject({ code: 'oauth_resource_mismatch' });
    // Atlassian 형: 보호 자원 메타데이터 없음 → MCP 출처의 인증 서버 메타데이터(issuer 가 그 출처)
    serve({ 'https://mcp.vendor-b.com/.well-known/oauth-authorization-server': { issuer: 'https://mcp.vendor-b.com', authorization_endpoint: 'https://mcp.vendor-b.com/v1/authorize', token_endpoint: 'https://mcp.vendor-b.com/v1/token', code_challenge_methods_supported: ['S256'] } });
    const b = await discoverResource(env, 'https://mcp.vendor-b.com/v1/mcp', 'Bearer realm="OAuth"');
    expect(b).toMatchObject({ resource: 'https://mcp.vendor-b.com/v1/mcp', authorizationServers: ['https://mcp.vendor-b.com'], legacy: true });
    // 출처의 issuer 가 다르면 옛 규격으로도 받지 않는다
    serve({ 'https://mcp.vendor-b.com/.well-known/oauth-authorization-server': { issuer: 'https://other.example', authorization_endpoint: 'x', token_endpoint: 'y' } });
    await expect(discoverResource(env, 'https://mcp.vendor-b.com/v1/mcp', null)).rejects.toMatchObject({ code: 'oauth_no_metadata' });
  } finally {
    globalThis.fetch = real;
  }
});
