  const s = await p.api.post(`/api/w/${p.ws}/schedules`, { spaceId: p.space, agentId, input: '[[script:s41]] 보고', kind: 'recurring', repeat: { every: 'day', time: '09:00' } }, 201);
  await dueNow(p, s.id);
