test('새 버전을 발행해도 고정된 예약은 그 버전, 최신 추종은 권한이 늘면 멈춘다(43·44)', async () => {
  const p = await person('s43');
  await addModel(p);
  const { agentId, versionId: v1 } = await publishAgent(p, { tools: [{ connectionId: 'builtin', name: 'knowledge_search' }] });
  await script('s43', [{ text: '고정 버전' }]);
  const pinned = await p.api.post(`/api/w/${p.ws}/schedules`, { spaceId: p.space, agentId, input: '[[script:s43]] x', kind: 'recurring', repeat: { every: 'day', time: '09:00' } }, 201);
  const follow = await p.api.post(`/api/w/${p.ws}/schedules`, { spaceId: p.space, agentId, input: '[[script:s43]] y', kind: 'recurring', repeat: { every: 'day', time: '10:00' }, followLatest: true }, 201);
  // v2: 외부 쓰기 도구 추가(권한 증가)
  const d = await p.api.get(`/api/w/${p.ws}/agents/${agentId}`);
  await p.api.put(`/api/w/${p.ws}/agents/${agentId}/draft`, { config: { ...d.published.config, tools: [...d.published.config.tools, { connectionId: 'builtin', name: 'send_email' }] } });
  const v2 = (await p.api.post(`/api/w/${p.ws}/agents/${agentId}/publish`)).versionId;
  expect(v2).not.toBe(v1);
  await dueNow(p, pinned.id);
  await dueNow(p, follow.id);
  await cron(p);
  const run = (await sql(p, `SELECT agent_version_id FROM runs WHERE schedule_id = ?`, [pinned.id])).results[0]!;
  expect(run.agent_version_id).toBe(v1);
  const f = (await sql(p, `SELECT status, status_reason FROM schedules WHERE id = ?`, [follow.id])).results[0]!;
  expect(f.status).toBe('needs_review');
  expect(String(f.status_reason)).toContain('권한이 늘어');
  expect((await sql(p, `SELECT COUNT(*) AS n FROM runs WHERE schedule_id = ?`, [follow.id])).results[0]!.n).toBe(0);
});

test('팀 서비스 주체는 위임한 도구·대상 안에서만 — 밖은 승인 대기, 위임 안 한 도구는 없음(7)', async () => {
  const owner = await person('s7');
  const { id: ws } = await owner.api.post('/api/workspaces', { name: `팀 s7` }, 201);
  const home = await owner.api.get(`/api/w/${ws}`);
  const teamSpace = home.spaces.find((s: { kind: string }) => s.kind === 'team').id;
  const o: Person = { ...owner, ws, space: teamSpace };
  // 팀원 한 명(수신처 후보)
  const memberAddr = email('s7m');
  const before = new Set((await mailsTo(memberAddr)).map((m) => m.id));
  await owner.api.post(`/api/w/${ws}/invitations`, { email: memberAddr, role: 'runner', spaceId: teamSpace }, 201);
  const token = (await waitNewMail(memberAddr, /초대/, before)).text.match(/\/invite\/([0-9a-f]{64})/)![1];
  await (await login(memberAddr)).post(`/api/invitations/${token}/accept`);
  await addModel(o, { ws, scope: 'workspace' });
  const { agentId } = await publishAgent(o, { ws, space: teamSpace, tools: [{ connectionId: 'builtin', name: 'send_email' }, { connectionId: 'builtin', name: 'knowledge_search' }] });
  await script('s7', [
    { toolCalls: [{ name: 'send_email', args: { to: [owner.email], subject: 's7-위임', body: '주간 보고' } }] },
    { toolCalls: [{ name: 'send_email', args: { to: [memberAddr], subject: 's7-밖', body: '다른 수신처' } }] },
    { text: '끝' },
  ]);
  const s = await o.api.post(`/api/w/${ws}/schedules`, { spaceId: teamSpace, agentId, input: '[[script:s7]] 보고', kind: 'recurring', repeat: { every: 'week', days: [1], time: '09:00' }, principalKind: 'service', writes: [{ connectionId: 'builtin', name: 'send_email', targets: [`to: ${owner.email}`] }] }, 201);
  const det = await o.api.get(`/api/w/${ws}/schedules/${s.id}`);
  expect(det.delegation.kind).toBe('service');
  await dueNow(o, s.id);
  await cron(o);
  const runId = (await sql(o, `SELECT id FROM runs WHERE schedule_id = ?`, [s.id])).results[0]!.id as string;
  const d = await waitRun(o, runId, { ws });
  expect(d.run.status).toBe('waiting_approval');
  const invs = d.invocations as { tool_name: string; status: string; targets: string[] }[];
  expect(invs.find((i) => i.targets.includes(`to: ${owner.email}`))!.status).toBe('succeeded'); // 위임 범위 안 → 승인 없이
  expect(invs.find((i) => i.targets.includes(`to: ${memberAddr}`))!.status).toBe('awaiting_approval'); // 밖 → 승인 대기
  expect((await mailsTo(owner.email)).filter((m) => m.subject === 's7-위임')).toHaveLength(1);
  expect((await mailsTo(memberAddr)).filter((m) => m.subject === 's7-밖')).toHaveLength(0);
  // 승인 요청 메일이 위임자에게 — 메일을 여는 것만으로는 승인되지 않는다
  const ask = (await mailsTo(owner.email)).find((m) => m.subject.includes('승인이 필요한 동작'))!;
  expect(ask.text).toContain('승인되지 않습니다');
  // 워크스페이스 밖 주소로의 발송 위임은 만들 수 없다
  const bad = await o.api.raw('POST', `/api/w/${ws}/schedules`, { spaceId: teamSpace, agentId, input: 'x', kind: 'recurring', repeat: { every: 'day', time: '09:00' }, principalKind: 'service', writes: [{ connectionId: 'builtin', name: 'send_email', targets: ['to: outsider@evil.example'] }] });
  expect(bad.status()).toBe(400);
  // 위임 기간이 끝나면 다음 회차는 실행하지 않고 재확인
  await sql(o, `UPDATE delegation_grants SET expires_at = ? WHERE id = (SELECT delegation_id FROM schedules WHERE id = ?)`, [Date.now() - 1000, s.id]);
  await o.api.post(`/api/w/${ws}/runs/${runId}/cancel`);
  await sleep(300);
  await dueNow(o, s.id);
  await cron(o);
  expect((await sql(o, `SELECT status FROM schedules WHERE id = ?`, [s.id])).results[0]!.status).toBe('needs_review');
  expect((await sql(o, `SELECT COUNT(*) AS n FROM runs WHERE schedule_id = ?`, [s.id])).results[0]!.n).toBe(1);
});

