/**
 * 시험 도우미 — 사람마다 따로 로그인한 요청 컨텍스트, 가짜 서버 제어, 실행 기다리기.
 * 로그인 코드는 가짜 Resend(:8871)가 받은 메일에서 읽는다. 접속 IP 는 사람마다 다르게(로그인 속도 제한 회피 —
 * 운영에서는 Cloudflare 가 CF-Connecting-IP 를 덮어쓰므로 사용자가 바꿀 수 없다).
 */
import { expect, request, type APIRequestContext, type APIResponse } from '@playwright/test';
import { randomBytes } from 'node:crypto';

export const BASE = 'http://127.0.0.1:8870';
export const MAIL = 'http://127.0.0.1:8871';
export const LLM = 'http://127.0.0.1:8872';
export const MCP = 'http://127.0.0.1:8873';
export const PORTAL = 'http://127.0.0.1:8874';
export const AS = 'http://127.0.0.1:8875';
export const OPERATOR = 'ops@irumx.test';
export const run = `${Date.now().toString(36)}${randomBytes(2).toString('hex')}`;
export const fakeIp = () => `10.${randomBytes(1)[0]}.${randomBytes(1)[0]}.${(randomBytes(1)[0]! % 250) + 1}`;
export const email = (tag: string) => `${tag}-${randomBytes(3).toString('hex')}-${run}@agent.test`.toLowerCase();
export const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

interface Mail {
  id: string;
  at: number;
  to: string[];
  subject: string;
  text: string;
  idempotencyKey: string | null;
}

export const mailsTo = async (to: string): Promise<Mail[]> => (await (await fetch(`${MAIL}/__mails?to=${encodeURIComponent(to)}`)).json()) as Mail[];

export async function waitNewMail(to: string, subject: RegExp, before: Set<string>, timeout = 15_000): Promise<Mail> {
  const end = performance.now() + timeout;
  while (performance.now() < end) {
    const m = (await mailsTo(to)).filter((x) => !before.has(x.id) && subject.test(x.subject)).at(-1);
    if (m) return m;
    await sleep(150);
  }
  throw new Error(`새 메일 없음: ${to} ${subject}`);
}

export class Api {
  constructor(
    public ctx: APIRequestContext,
    public email: string,
  ) {}
  async get(path: string, status = 200) {
    const r = await this.ctx.get(path);
    await expectStatus(r, status, `GET ${path}`);
    return r.status() < 300 ? r.json() : r.json().catch(() => null);
  }
  async post(path: string, data: unknown = {}, status = 200, headers: Record<string, string> = {}) {
    const r = await this.ctx.post(path, { data, headers: { 'Content-Type': 'application/json', ...headers } });
    await expectStatus(r, status, `POST ${path}`);
    return r.json().catch(() => null);
  }
  async put(path: string, data: unknown, status = 200) {
    const r = await this.ctx.put(path, { data, headers: { 'Content-Type': 'application/json' } });
    await expectStatus(r, status, `PUT ${path}`);
    return r.json().catch(() => null);
  }
  async del(path: string, status = 200) {
    const r = await this.ctx.delete(path);
    await expectStatus(r, status, `DELETE ${path}`);
    return r.json().catch(() => null);
  }
  async raw(method: 'GET' | 'POST' | 'PUT' | 'DELETE', path: string, data?: unknown, headers: Record<string, string> = {}) {
    return this.ctx.fetch(path, { method, data, headers: { ...(data !== undefined && typeof data !== 'string' && !Buffer.isBuffer(data) ? { 'Content-Type': 'application/json' } : {}), ...headers } });
  }
}

export async function expectStatus(r: APIResponse, status: number, label: string) {
  if (r.status() !== status) throw new Error(`${label} → ${r.status()} (기대 ${status}): ${(await r.text()).slice(0, 500)}`);
}

export async function login(addr: string): Promise<Api> {
  const ctx = await request.newContext({ baseURL: BASE, extraHTTPHeaders: { Origin: BASE, 'CF-Connecting-IP': fakeIp() } });
  const before = new Set((await mailsTo(addr)).map((m) => m.id));
  const s = await ctx.post('/api/auth/email-otp/send-verification-otp', { data: { email: addr, type: 'sign-in' } });
  expect(s.status(), await s.text()).toBe(200);
  const code = (await waitNewMail(addr, /로그인 코드/, before)).subject.match(/\d{6}/)![0];
  const v = await ctx.post('/api/auth/sign-in/email-otp', { data: { email: addr, otp: code } });
  expect(v.status(), await v.text()).toBe(200);
  return new Api(ctx, addr);
}

/** 운영자 세션은 한 번만 만든다 — 로그인 코드는 주소마다 15분에 5번까지라, 시험마다 새로 받으면 연달아 돌릴 때 막힌다 */
let opSession: Promise<Api> | null = null;
export const operator = () => (opSession ??= login(OPERATOR));

export interface Person {
  api: Api;
  email: string;
  id: string;
  ws: string;
  space: string;
}

/** 새 사람 — 가입하면 1인 워크스페이스와 개인 공간이 생긴다 */
export async function person(tag: string): Promise<Person> {
  const addr = email(tag);
  const api = await login(addr);
  const me = await api.get('/api/me');
  const w = me.workspaces.find((x: { kind: string }) => x.kind === 'personal');
  return { api, email: addr, id: me.user.id, ws: w.id, space: w.personalSpaceId };
}

/** 가짜 모델 대본 등록. 입력에 [[script:name]] 을 넣으면 그 대본을 따른다 */
export async function script(name: string, steps: Record<string, unknown>[]) {
  await fetch(`${LLM}/__script`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, steps }) });
}
export const llmRequests = async (last = 20) => (await (await fetch(`${LLM}/__requests?last=${last}`)).json()) as { body: Record<string, unknown>; key: string; headers: Record<string, string | null> }[];

export const mcpControl = (c: Record<string, unknown>) => fetch(`${MCP}/__control`, { method: 'POST', body: JSON.stringify(c) });
export const mcpLog = async () => (await (await fetch(`${MCP}/__log`)).json()) as Record<string, unknown>[];
export const mcpCalls = async () => (await (await fetch(`${MCP}/__calls`)).json()) as { created: { tool: string; args: Record<string, unknown> }[]; refreshCalls: number };
export const mcpReset = () => fetch(`${MCP}/__log`, { method: 'DELETE' });

/** 모델 연결(가짜 Anthropic) 등록 + 시험 */
export async function addModel(p: Person, opts: { provider?: 'anthropic' | 'openai_compat'; scope?: 'personal' | 'workspace'; key?: string; ws?: string } = {}) {
  const ws = opts.ws ?? p.ws;
  const provider = opts.provider ?? 'anthropic';
  const { id } = await p.api.post(
    `/api/w/${ws}/models`,
    provider === 'anthropic'
      ? { scope: opts.scope ?? 'personal', provider, model: 'claude-sonnet-5-5', baseUrl: LLM, apiKey: opts.key ?? 'sk-ant-test-key-0001' }
      : { scope: opts.scope ?? 'personal', provider, model: 'mock-model', baseUrl: `${LLM}/v1`, apiKey: opts.key ?? 'sk-test-key-0002' },
    201,
  );
  const t = await p.api.post(`/api/w/${ws}/models/${id}/test`);
  expect(t.status, JSON.stringify(t)).toBe('ok');
  return id as string;
}

/** 에이전트 만들고(템플릿) 설정 저장 후 발행 */
export async function publishAgent(p: Person, opts: { ws?: string; space?: string; template?: string; tools?: { connectionId: string; name: string }[]; share?: string; config?: Record<string, unknown>; name?: string } = {}) {
  const ws = opts.ws ?? p.ws;
  const { id } = await p.api.post(`/api/w/${ws}/agents`, { spaceId: opts.space ?? p.space, templateKey: opts.template ?? 'personal-assistant', name: opts.name ?? `에이전트 ${run}` }, 201);
  const d = await p.api.get(`/api/w/${ws}/agents/${id}`);
  const config = { ...d.draft.config, ...(opts.tools ? { tools: opts.tools } : {}), ...(opts.config ?? {}) };
  await p.api.put(`/api/w/${ws}/agents/${id}/draft`, { config, shareScope: opts.share ?? 'private' });
  const pub = await p.api.post(`/api/w/${ws}/agents/${id}/publish`);
  return { agentId: id as string, versionId: pub.versionId as string };
}

export async function chat(p: Person, agentId: string, content: string, opts: { ws?: string; space?: string; status?: number } = {}) {
  const ws = opts.ws ?? p.ws;
  const { id: conv } = await p.api.post(`/api/w/${ws}/spaces/${opts.space ?? p.space}/conversations`, { agentId }, 201);
  const r = await p.api.post(`/api/w/${ws}/conversations/${conv}/messages`, { content }, opts.status ?? 202);
  return { conv: conv as string, runId: r?.runId as string };
}

const STOP = ['succeeded', 'failed', 'cancelled', 'expired', 'waiting_approval', 'waiting_input', 'waiting_connection', 'paused_budget', 'waiting_reconciliation'];

/** 실행이 멈추는 상태(끝·대기)에 이를 때까지 */
export async function waitRun(p: Person, runId: string, opts: { ws?: string; until?: string[]; timeout?: number } = {}) {
  const ws = opts.ws ?? p.ws;
  const until = opts.until ?? STOP;
  const end = performance.now() + (opts.timeout ?? 60_000);
  let last: { run: { status: string } } | null = null;
  while (performance.now() < end) {
    last = await p.api.get(`/api/w/${ws}/runs/${runId}`);
    if (until.includes(last!.run.status)) return last as Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
    await sleep(400);
  }
  throw new Error(`실행이 ${until.join('/')} 에 이르지 않음: ${last?.run.status}`);
}

