/**
 * 예약 작업 — 고객마다 Cloudflare Cron 을 만들지 않는다. schedules.next_run_at(UTC)을 공용 scheduler(1분 Cron)가 본다.
 *
 * - 시각: IANA 타임존 벽시계로 해석(기본 Asia/Seoul), 저장·비교는 UTC. 서머타임 사라지는 시각은 정책(skip/shift), 겹치는 시각은 한 번.
 * - 고정: 에이전트 발행 버전·일정 버전·위임(도구·쓰기 대상·횟수·비용·만료). 최신 버전 추종은 선택이며 권한이 늘면 멈추고 재확인.
 * - 중복: (일정, 일정 버전, 발생 시각) 고유 + next_run_at 조건부 갱신 — 같은 회차는 실행 하나뿐.
 * - 겹침: 이전 실행이 안 끝났으면 건너뜀. 누락: 밀린 회차는 최대 한 번만 따라잡고 나머지는 한 줄로 '건너뜀' 기록.
 * - 실행 주체: 세션 쿠키가 아니라 위임(개인) 또는 서비스 주체. 매번 지금 권한을 다시 본다.
 */
import { Tx } from '../db/client';
import { ApiError, bad, conflict } from '../lib/errors';
import { newId, parseJson } from '../lib/util';
import { canSpace, type ToolRisk } from '../../shared/domain';
import { CronError, isTimeZone, localToUtc, nextRuns, parseCron, parseLocal, repeatToCron, type GapPolicy, type Repeat } from '../../shared/cron';
import { principalRoles } from '../policies/access';
import { acceptRun, agentUsable, platformStopped, type AgentRow, type VersionRow } from './runs';
import { audit } from './audit';
import type { PinnedTool } from './tools';

export const MIN_INTERVAL_MS = 15 * 60_000;
export const CATCHUP_GRACE_MS = 15 * 60_000;

export interface SchedulePlan {
  kind: 'once' | 'recurring';
  cron: string | null;
  runAtLocal: string | null;
  timezone: string;
  gapPolicy: GapPolicy;
}

/** 입력 검증 + 다음 5회 */
export function planSchedule(input: { kind: unknown; repeat?: unknown; runAtLocal?: unknown; timezone?: unknown; gapPolicy?: unknown }, now = Date.now()): { plan: SchedulePlan; next: { utc: number; note?: string }[] } {
  const timezone = typeof input.timezone === 'string' && input.timezone ? input.timezone : 'Asia/Seoul';
  if (!isTimeZone(timezone)) throw bad('타임존 이름이 올바르지 않습니다(예: Asia/Seoul).');
  const gapPolicy: GapPolicy = input.gapPolicy === 'shift' ? 'shift' : 'skip';
  if (input.kind === 'once') {
    const w = parseLocal(String(input.runAtLocal ?? ''));
    if (!w) throw bad('실행 시각을 YYYY-MM-DDTHH:MM 으로 적어 주세요.');
    const r = localToUtc(w, timezone);
    if (r.kind === 'gap') throw bad('그 시각은 서머타임 전환으로 존재하지 않습니다. 다른 시각을 골라 주세요.');
    if (r.utc <= now + 60_000) throw bad('실행 시각은 지금보다 1분 이상 뒤여야 합니다.');
    return { plan: { kind: 'once', cron: null, runAtLocal: String(input.runAtLocal), timezone, gapPolicy }, next: [{ utc: r.utc, ...(r.kind === 'overlap' ? { note: 'overlap_once' } : {}) }] };
  }
  if (input.kind !== 'recurring') throw bad('일회성(once) 또는 반복(recurring)을 골라 주세요.');
  let cron: string;
  try {
    cron = repeatToCron(input.repeat as Repeat);
    const spec = parseCron(cron);
    const next = nextRuns(spec, timezone, now, 6, gapPolicy);
    if (!next.length) throw bad('앞으로 5년 안에 실행될 시각이 없습니다.');
    for (let i = 1; i < next.length; i++) if (next[i]!.utc - next[i - 1]!.utc < MIN_INTERVAL_MS) throw bad(`반복 간격은 ${MIN_INTERVAL_MS / 60_000}분 이상이어야 합니다(서비스 정책).`);
    return { plan: { kind: 'recurring', cron, runAtLocal: null, timezone, gapPolicy }, next: next.slice(0, 5) };
  } catch (e) {
    if (e instanceof CronError) throw bad(e.message);
    throw e;
  }
}

export function nextAfter(s: { kind: string; cron: string | null; timezone: string; gap_policy: string }, after: number): number | null {
  if (s.kind === 'once' || !s.cron) return null;
  return nextRuns(parseCron(s.cron), s.timezone, after, 1, s.gap_policy as GapPolicy)[0]?.utc ?? null;
}

export interface DelegationToolInput {
  connectionId: string;
  name: string;
  /** 쓰기 도구를 위임할 때 허용 대상(예: 'to: a@b.c') */
  targets?: string[];
}

/** 위임할 도구 — 발행 버전에 고정된 도구 중에서. 쓰기는 사용자가 고르고 대상을 적은 것만 */
export function delegationTools(pinned: PinnedTool[], writes: DelegationToolInput[]): { connectionId: string; name: string; schemaHash: string; risk: ToolRisk; targets?: string[] }[] {
  const out: { connectionId: string; name: string; schemaHash: string; risk: ToolRisk; targets?: string[] }[] = [];
  for (const t of pinned) {
    if (t.risk === 'high') continue;
    if (t.risk !== 'write') {
      out.push({ connectionId: t.connectionId, name: t.name, schemaHash: t.schemaHash, risk: t.risk });
      continue;
    }
    const w = writes.find((x) => x.connectionId === t.connectionId && x.name === t.name);
    const targets = (w?.targets ?? []).map((x) => String(x).trim()).filter(Boolean).slice(0, 10);
    if (w && targets.length) out.push({ connectionId: t.connectionId, name: t.name, schemaHash: t.schemaHash, risk: 'write', targets });
  }
  return out;
}
